import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    if not url or not filename:
        return ("Error: url and filename must be non-empty", [])

    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)

    zip_path = DOWNLOAD_DIR / filename

    try:
        response = requests.get(url, stream=True, timeout=10)
        response.raise_for_status()
    except requests.RequestException as e:
        return (f"Error: Network issue during download: {e}", [])

    try:
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except IOError as e:
        return (f"Error: Failed to write zip file: {e}", [])

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            zf.extractall(ZIP_DIR)
    except (zipfile.BadZipFile, IOError) as e:
        return (f"Error: Failed to extract zip file: {e}", [])

    extracted_files = [f.name for f in ZIP_DIR.iterdir() if f.is_file()]
    return ("Successfully downloaded and extracted", extracted_files)

