import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url, timeout=10)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(str(e))
    tree = html.fromstring(response.content)
    table_list = tree.xpath('//table')
    if not table_list:
        return 0
    table = table_list[0]
    headers = [th.text_content().strip() for th in table.xpath('.//th')]
    data = []
    for tr in table.xpath('.//tr'):
        tds = tr.xpath('.//td')
        if not tds:
            continue
        row = [td.text_content().strip() for td in tds]
        data.append(row)
    if not data:
        return 0
    df = pd.DataFrame(data, columns=headers if headers else None)
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.Error as e:
        raise sqlite3.DatabaseError(str(e))
    return len(df)

import requests
import pandas as pd
import sqlite3
from io import StringIO
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if webpage_url.startswith("http://") or webpage_url.startswith("https://"):
        try:
            verify = False if ("localhost" in webpage_url or "dev." in webpage_url) else True
            response = requests.get(webpage_url, verify=verify)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(f"Network error: {e}")
    else:
        try:
            with open(webpage_url, "r", encoding="utf-8") as f:
                content = f.read()
        except FileNotFoundError as e:
            raise requests.RequestException(f"File not found: {e}")
    try:
        tables = pd.read_html(StringIO(content), flavor="lxml")
        if not tables:
            return 0
        df = tables[0]
        if df.empty:
            return 0
    except ValueError:
        return 0
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return len(df)

