import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network error while fetching URL: {e}") from e

    tree = html.fromstring(response.content)
    table = tree.find('.//table')
    if table is None:
        return 0

    headers = [th.text_content().strip() for th in table.findall('.//th')]
    rows = []
    for tr in table.findall('.//tr'):
        cells = tr.findall('.//td')
        if cells:
            rows.append([cell.text_content().strip() for cell in cells])

    if not rows:
        return 0

    if headers:
        df = pd.DataFrame(rows, columns=headers)
    else:
        df = pd.DataFrame(rows)

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}") from e
    finally:
        if 'conn' in locals():
            conn.close()

    return len(df)

