import requests
import logging
def task_func(repo_url: str) -> dict:
    if not repo_url:
        raise ValueError("URL must be a non-empty string.")
    logger = logging.getLogger(__name__)
    try:
        response = requests.get(repo_url, timeout=10)
        if response.status_code == 403:
            remaining = response.headers.get('X-RateLimit-Remaining', '1')
            if remaining == '0':
                raise requests.exceptions.HTTPError("GitHub API rate limit exceeded.")
        response.raise_for_status()
        data = response.json()
        threshold = 100
        open_issues = data.get('open_issues_count', 0)
        if open_issues > threshold:
            logger.warning(f"Repository has {open_issues} open issues, which exceeds threshold {threshold}.")
        return data
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Request error: {e}")

