        try:
            ip = socket.gethostbyname(domain)
            response = requests.get(f'https://api.ipapi.com/{ip}?access_key={API_KEY}', timeout=10)
            if response.status_code == 200:
                data = response.json()
                result[domain] = data
            else:
                result[domain] = None
        except Exception:
            result[domain] = None
    return result

