import json
import requests
import os
from datetime import datetime
def task_func(json_data, unknown_key, save_dir=None):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON string: {e}") from e
    if unknown_key not in data:
        raise KeyError(f"Key '{unknown_key}' not found in JSON data.")
    url = data[unknown_key]
    if not isinstance(url, str) or not url:
        raise ValueError("URL must be a non-empty string.")
    timestamp = datetime.utcnow().strftime('%Y%m%d%H%M%S%f')
    filename = f"{unknown_key}_{timestamp}.txt"
    if save_dir:
        os.makedirs(save_dir, exist_ok=True)
        filepath = os.path.join(save_dir, filename)
    else:
        filepath = os.path.join(os.getcwd(), filename)
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException as e:
        raise RuntimeError(f"Failed to download from {url}: {e}") from e
    try:
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(response.text)
    except IOError as e:
        raise IOError(f"Failed to write file {filepath}: {e}") from e
    return os.path.abspath(filepath)

