import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    if not user or not isinstance(user, str):
        raise ValueError("User must be a non-empty string.")

    repos_info = []
    page = 1
    session = requests.Session()
    session.headers.update({'User-Agent': 'task_func/1.0'})

    while True:
        url = f"{API_URL}{user}/repos?page={page}&per_page=100"
        try:
            resp = session.get(url)
        except requests.RequestException as e:
            raise ConnectionError(f"Failed to connect to GitHub API: {e}")

        if resp.status_code == 404:
            raise ValueError(f"User '{user}' not found.")
        if resp.status_code != 200:
            raise ConnectionError(f"GitHub API returned status {resp.status_code}.")

        data = resp.json()
        if not data:
            break

        for repo in data:
            name = repo.get('name')
            created_at = repo.get('created_at')
            if name and created_at:
                repos_info.append((name, created_at))

        if 'next' in resp.links:
            page += 1
        else:
            break

    if not repos_info:
        return []

    repos_info.sort(key=lambda x: x[1])
    return [name for name, _ in repos_info]

