import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not url or not destination_directory:
        raise ValueError("URL and destination_directory must be provided.")
    if headers is None:
        headers = {}
    try:
        url_legacy_compatible = 'localhost' in url or 'dev.' in url
        verify_cert = False if url_legacy_compatible else True
        response = requests.get(url, stream=True, headers=headers, verify=verify_cert)
        response.raise_for_status()
        temp_path = os.path.join(destination_directory, '__temp_download.zip')
        os.makedirs(destination_directory, exist_ok=True)
        with open(temp_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
        extracted_files = []
        with zipfile.ZipFile(temp_path, 'r') as zf:
            zf.extractall(destination_directory)
            for name in zf.namelist():
                # ensure we only list files (not directories)
                full_path = os.path.join(destination_directory, name)
                if os.path.isfile(full_path):
                    extracted_files.append(name)
        return extracted_files
    except (requests.exceptions.RequestException, zipfile.BadZipFile) as e:
        raise ConnectionError(f"Failed to download or extract zip from {url}: {e}")
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)

